class HomeCatePojo {
  int? _status;
  String? _message;
  int? _messageCode;
  int? _totalOngoingOrder;
  int? _totalUnreadMessage;
  List<ServicesItem>? _services;
  List<HomeSliderItem>? _homeSlider;
  bool? _reenSportsMode;
  ActiveSportsClub? _activeSportsClub;

  String get message => _message ?? "";

  int get status => _status ?? 0;

  int get messageCode => _messageCode ?? 0;

  int get totalOngoingOrder => _totalOngoingOrder ?? 0;

  int get totalUnreadMessage => _totalUnreadMessage ?? 0;

  List<ServicesItem> get services => _services ?? [];

  List<HomeSliderItem> get homeSlider => _homeSlider ?? [];

  bool get reenSportsMode => _reenSportsMode ?? false;

  ActiveSportsClub? get activeSportsClub => _activeSportsClub;

  HomeCatePojo(
      {int? status,
      String? message,
      int? messageCode,
      int? totalOngoingOrder,
      int? totalUnreadMessage,
      List<ServicesItem>? services,
      List<HomeSliderItem>? homeSlider,
      bool? reenSportsMode,
      ActiveSportsClub? activeSportsClub}) {
    _status = status;
    _message = message;
    _messageCode = messageCode;
    _totalOngoingOrder = totalOngoingOrder;
    _totalUnreadMessage = totalUnreadMessage;
    _services = services;
    _homeSlider = homeSlider;
    _reenSportsMode = reenSportsMode;
    _activeSportsClub = activeSportsClub;
  }

  HomeCatePojo.fromJson(dynamic json) {
    _status = json["status"];
    _message = json["message"];
    _messageCode = json["message_code"];
    _totalOngoingOrder = json["total_ongoing_order"];
    _totalUnreadMessage = json["total_unread_message"];
    _reenSportsMode = json["reen_sports_mode"] == 1 ||
        json["reen_sports_mode"] == true;
    if (json["active_sports_club"] != null) {
      _activeSportsClub =
          ActiveSportsClub.fromJson(json["active_sports_club"]);
    }
    if (json["services"] != null) {
      _services = [];
      json["services"].forEach((v) {
        _services?.add(ServicesItem.fromJson(v));
      });
    }
    if (json["home_slider"] != null) {
      _homeSlider = [];
      json["home_slider"].forEach((v) {
        _homeSlider?.add(HomeSliderItem.fromJson(v));
      });
    }
  }

  Map<String?, dynamic> toJson() {
    var map = <String?, dynamic>{};
    map["status"] = _status;
    map["message"] = _message;
    map["message_code"] = _messageCode;
    map["total_ongoing_order"] = _totalOngoingOrder;
    map["total_unread_message"] = _totalUnreadMessage;
    map["reen_sports_mode"] = _reenSportsMode;
    if (_activeSportsClub != null) {
      map["active_sports_club"] = _activeSportsClub!.toJson();
    }
    if (_services != null) {
      map["services"] = _services?.map((v) => v.toJson()).toList();
    }
    if (_homeSlider != null) {
      map["home_slider"] = _homeSlider?.map((v) => v.toJson()).toList();
    }
    return map;
  }
}

